    eval("{\n/**\n * ★★★ 悬浮球 + 每楼完整面板\n *\n * ★ 用户报的：\n *   · \"悬浮的按钮我没有看到\"\n *   · \"二楼三楼的底部也没有其他状态栏，或者没有看到控制中心\"\n *\n * ★ 这个脚本做两件事：\n *   ① 悬浮球 —— 随时打开完整面板（显示手机等级，可拖、可吸边）\n *   ② ★ 每楼补面板 —— 不靠 AI 记得输出 <面板/>，脚本自己补漏掉的楼层\n *\n * ★ 设计要点（照 C11 规范）：\n *   · 入口只做入口 —— 面板内容在 CDN 的界面里，不在这里重复实现\n *   · 用 Pointer Events（含 pointercancel 清理）\n *   · 位置持久化 + resize 后重新夹取\n *   · pagehide 清理\n *   · ★ 闲置时半透明，不提供\"隐藏\" —— 免得玩家找不回来\n */\n// ★★★ 面板地址：用 @main 而不是钉死的 commit\n//   原因：这个脚本自己也在 CDN 上，钉死 commit 会变成鸡生蛋 ——\n//        每次改面板都要改脚本、重推、再改回来。\n//   ★ 面板是纯前端，跟着 main 走没有副作用。\nconst 面板地址 = 'https://testingcf.jsdelivr.net/gh/fkgzs123321/galgame-shenqishouji@main/index.html';\nconst 球ID = 'dsh-orb';\nconst 窗ID = 'dsh-orb-win';\nconst 样式ID = 'dsh-orb-style';\nconst 层ID = 'dsh-floor-panel';\nconst 存位键 = 'dsh.orb.pos';\n/** ★ 宿主文档：脚本可能跑在主页面，也可能跑在 iframe 里 —— 两种都兜住 */\nfunction 宿主文档() {\n    try {\n        const p = window.parent;\n        if (p && p !== window && p.document && p.document.body)\n            return p.document;\n    }\n    catch {\n        /* 跨域就退回自己 */\n    }\n    return document;\n}\n/** ★ 读手机等级（读不到就显示 ·） */\nfunction 读等级() {\n    try {\n        const v = getVariables({ type: 'message', message_id: -1 });\n        const lv = v?.stat_data?.手机?.等级;\n        return typeof lv === 'number' ? String(lv) : '·';\n    }\n    catch {\n        return '·';\n    }\n}\n/** ★ 球的 tooltip */\nfunction 读摘要() {\n    try {\n        const v = getVariables({ type: 'message', message_id: -1 });\n        const s = v?.stat_data;\n        if (!s)\n            return '';\n        const 钱 = Number(s.玩家?.现金 ?? 0);\n        const 阅 = Number(s.阅历?.可用 ?? 0);\n        return `Lv${s.手机?.等级 ?? '·'}　¥${钱.toLocaleString()}　阅历 ${阅}`;\n    }\n    catch {\n        return '';\n    }\n}\n// ══════════════════════════════════════════\n// ② ★ 每楼补面板 —— 只补【漏掉的】楼层\n// ══════════════════════════════════════════\nfunction 补楼层面板() {\n    const d = 宿主文档();\n    let 楼层 = [];\n    try {\n        楼层 = getChatMessages('0-{{lastMessageId}}') ?? [];\n    }\n    catch {\n        return;\n    }\n    if (!Array.isArray(楼层) || !楼层.length)\n        return;\n    for (const m of 楼层) {\n        if (m.role !== 'assistant')\n            continue;\n        // ★ 正则已经把 <面板/> 渲染成面板了 —— 有就不补\n        const 文本 = String(m.message ?? '');\n        if (文本.includes('<面板/>') || 文本.includes('StatusPlaceHolderImpl'))\n            continue;\n        // ★ 这一楼的 DOM\n        const 楼 = d.querySelector(`.mes[mesid=\"${m.message_id}\"] .mes_text`);\n        if (!楼)\n            continue;\n        let 父 = 楼.parentElement;\n        if (!父)\n            continue;\n        if (父.querySelector(`.${层ID}`))\n            continue;\n        const 包 = d.createElement('div');\n        包.className = 层ID;\n        包.style.cssText =\n            'margin-top:10px;height:60vh;min-height:260px;max-height:700px;' +\n                'border:1px solid #2e2745;border-radius:11px;overflow:hidden;background:#0b0b12;';\n        const f = d.createElement('iframe');\n        f.src = `${面板地址}?mid=${m.message_id}`;\n        f.style.cssText = 'width:100%;height:100%;border:0;background:#0b0b12;';\n        f.setAttribute('allow', 'clipboard-read; clipboard-write');\n        包.appendChild(f);\n        父.appendChild(包);\n    }\n}\n// ══════════════════════════════════════════\n// 样式\n// ══════════════════════════════════════════\nconst 样式 = `\r\n#${球ID} {\r\n  position: fixed; z-index: 999998; width: 52px; height: 52px;\r\n  border-radius: 50%; display: flex; flex-direction: column;\r\n  align-items: center; justify-content: center;\r\n  background: radial-gradient(circle at 32% 28%, #4a3a6a, #1a1626 70%);\r\n  border: 1px solid #6c5a9a; box-shadow: 0 4px 18px rgba(0,0,0,.55);\r\n  cursor: grab; user-select: none; touch-action: none;\r\n  opacity: .38; transition: opacity .18s, transform .18s, box-shadow .18s;\r\n  font-family: ui-monospace, Consolas, monospace;\r\n}\r\n#${球ID}:hover { opacity: 1; transform: scale(1.08); box-shadow: 0 6px 22px rgba(120,90,200,.6); }\r\n#${球ID}.on { opacity: 1; border-color: #b08cff; box-shadow: 0 0 16px rgba(160,120,255,.7); }\r\n#${球ID}.drag { cursor: grabbing; opacity: 1; transform: scale(1.12); }\r\n#${球ID} .dsh-orb-ico { font-size: 20px; line-height: 1; }\r\n#${球ID} .dsh-orb-lv { font-size: 9px; line-height: 1; margin-top: 2px; color: #d8c8ff; letter-spacing: -.3px; }\r\n\r\n#${窗ID} {\r\n  position: fixed; z-index: 999999; width: 388px; height: 66vh;\r\n  max-height: 720px; min-width: 280px; min-height: 260px;\r\n  display: flex; flex-direction: column;\r\n  background: #0b0b12; border: 1px solid #3a3355; border-radius: 13px;\r\n  box-shadow: 0 18px 60px rgba(0,0,0,.75); overflow: hidden;\r\n  font-family: system-ui, -apple-system, \"Segoe UI\", sans-serif;\r\n}\r\n#${窗ID} .dsh-ow-bar {\r\n  display: flex; align-items: center; gap: 7px; padding: 7px 10px;\r\n  background: linear-gradient(180deg, #221c33, #171226);\r\n  border-bottom: 1px solid #2e2745; cursor: move; flex: 0 0 auto;\r\n}\r\n#${窗ID} .dsh-ow-t { flex: 1; font-size: 12px; color: #c8b8f0; letter-spacing: .5px; }\r\n#${窗ID} .dsh-ow-b {\r\n  width: 22px; height: 22px; border-radius: 6px; border: 1px solid #3a3355;\r\n  background: #1a1626; color: #9a8ac8; font-size: 12px; line-height: 1;\r\n  cursor: pointer; display: flex; align-items: center; justify-content: center; padding: 0;\r\n}\r\n#${窗ID} .dsh-ow-b:hover { background: #2a2340; color: #e0d0ff; border-color: #6a5a9a; }\r\n#${窗ID} iframe { flex: 1; width: 100%; border: 0; background: #0b0b12; }\r\n`;\nfunction 注入样式(d) {\n    if (d.getElementById(样式ID))\n        return;\n    const s = d.createElement('style');\n    s.id = 样式ID;\n    s.textContent = 样式;\n    d.head?.appendChild(s);\n}\nfunction 读位(d) {\n    try {\n        const raw = (d.defaultView ?? window).localStorage.getItem(存位键);\n        if (!raw)\n            return null;\n        const v = JSON.parse(raw);\n        if (typeof v?.x === 'number' && typeof v?.y === 'number')\n            return v;\n    }\n    catch {\n        /* 忽略 */\n    }\n    return null;\n}\nfunction 存位(d, p) {\n    try {\n        (d.defaultView ?? window).localStorage.setItem(存位键, JSON.stringify(p));\n    }\n    catch {\n        /* 忽略 */\n    }\n}\n/** ★ 夹回视口内 */\nfunction 夹取(p, d, 尺寸 = 52) {\n    const w = d.defaultView?.innerWidth ?? 1200;\n    const h = d.defaultView?.innerHeight ?? 800;\n    return {\n        x: Math.max(4, Math.min(w - 尺寸 - 4, p.x)),\n        y: Math.max(4, Math.min(h - 尺寸 - 4, p.y)),\n    };\n}\n// ══════════════════════════════════════════\n// 浮窗\n// ══════════════════════════════════════════\nfunction 开窗(d, 锚) {\n    if (d.getElementById(窗ID))\n        return;\n    const w = d.defaultView?.innerWidth ?? 1200;\n    const h = d.defaultView?.innerHeight ?? 800;\n    const 宽 = 388;\n    const 高 = Math.min(720, Math.max(260, h * 0.66));\n    // ★ 靠球的那一侧展开\n    let x = 锚.x + 62;\n    if (x + 宽 > w - 8)\n        x = 锚.x - 宽 - 10;\n    if (x < 8)\n        x = Math.max(8, (w - 宽) / 2);\n    const el = d.createElement('div');\n    el.id = 窗ID;\n    el.style.left = `${x}px`;\n    el.style.top = `${Math.max(8, Math.min(h - 高 - 8, 锚.y - 20))}px`;\n    el.style.height = `${高}px`;\n    el.innerHTML = `\r\n    <div class=\"dsh-ow-bar\">\r\n      <span class=\"dsh-ow-t\">📱 神奇手机</span>\r\n      <button class=\"dsh-ow-b\" data-a=\"reload\" title=\"重新载入面板\">⟳</button>\r\n      <button class=\"dsh-ow-b\" data-a=\"close\" title=\"关闭\">✕</button>\r\n    </div>\r\n    <iframe src=\"${面板地址}\" allow=\"clipboard-read; clipboard-write\"></iframe>\r\n  `;\n    d.body.appendChild(el);\n    el.querySelector('[data-a=\"close\"]')?.addEventListener('click', () => {\n        el.remove();\n        d.getElementById(球ID)?.classList.remove('on');\n    });\n    el.querySelector('[data-a=\"reload\"]')?.addEventListener('click', () => {\n        const f = el.querySelector('iframe');\n        if (f)\n            f.src = `${面板地址}?t=${Date.now()}`;\n    });\n    // ★ 标题栏拖动\n    const 栏 = el.querySelector('.dsh-ow-bar');\n    栏?.addEventListener('pointerdown', (e) => {\n        if (e.target.tagName === 'BUTTON')\n            return;\n        const r = el.getBoundingClientRect();\n        const dx = e.clientX - r.left;\n        const dy = e.clientY - r.top;\n        栏.setPointerCapture(e.pointerId);\n        const 移 = (ev) => {\n            const ww = d.defaultView?.innerWidth ?? 1200;\n            const wh = d.defaultView?.innerHeight ?? 800;\n            el.style.left = `${Math.max(0, Math.min(ww - r.width, ev.clientX - dx))}px`;\n            el.style.top = `${Math.max(0, Math.min(wh - 40, ev.clientY - dy))}px`;\n        };\n        const 停 = () => {\n            栏.removeEventListener('pointermove', 移);\n            栏.removeEventListener('pointerup', 停);\n            栏.removeEventListener('pointercancel', 停);\n        };\n        栏.addEventListener('pointermove', 移);\n        栏.addEventListener('pointerup', 停);\n        栏.addEventListener('pointercancel', 停);\n    });\n}\nfunction 关窗(d) {\n    d.getElementById(窗ID)?.remove();\n}\n// ══════════════════════════════════════════\n// 建球\n// ══════════════════════════════════════════\nfunction 建球() {\n    const d = 宿主文档();\n    if (d.getElementById(球ID))\n        return;\n    注入样式(d);\n    const 球 = d.createElement('div');\n    球.id = 球ID;\n    球.title = '手机 · 点开面板';\n    const w0 = d.defaultView?.innerWidth ?? 1200;\n    const h0 = d.defaultView?.innerHeight ?? 800;\n    const 初 = 读位(d) ?? { x: w0 - 72, y: h0 - 140 };\n    const p0 = 夹取(初, d);\n    球.style.left = `${p0.x}px`;\n    球.style.top = `${p0.y}px`;\n    球.innerHTML = '<span class=\"dsh-orb-ico\">📱</span><span class=\"dsh-orb-lv\"></span>';\n    d.body.appendChild(球);\n    const 写等级 = () => {\n        const e = 球.querySelector('.dsh-orb-lv');\n        if (e)\n            e.textContent = 读等级();\n        球.title = `手机 · 点开面板${读摘要() ? '\\n' + 读摘要() : ''}`;\n    };\n    写等级();\n    const 定时 = (d.defaultView ?? window).setInterval?.(写等级, 5000);\n    // ★ 拖动 + 点击（同一次 pointer 交互里区分）\n    let 按下 = false;\n    let 动了 = false;\n    let 起 = { x: 0, y: 0 };\n    let 起位 = { x: p0.x, y: p0.y };\n    球.addEventListener('pointerdown', (e) => {\n        按下 = true;\n        动了 = false;\n        起 = { x: e.clientX, y: e.clientY };\n        起位 = { x: parseFloat(球.style.left) || p0.x, y: parseFloat(球.style.top) || p0.y };\n        球.classList.add('drag');\n        球.setPointerCapture(e.pointerId);\n        e.preventDefault();\n    });\n    球.addEventListener('pointermove', (e) => {\n        if (!按下)\n            return;\n        const dx = e.clientX - 起.x;\n        const dy = e.clientY - 起.y;\n        if (!动了 && Math.hypot(dx, dy) < 5)\n            return;\n        动了 = true;\n        球.style.left = `${起位.x + dx}px`;\n        球.style.top = `${起位.y + dy}px`;\n    });\n    const 松 = (e) => {\n        if (!按下)\n            return;\n        按下 = false;\n        球.classList.remove('drag');\n        try {\n            球.releasePointerCapture(e.pointerId);\n        }\n        catch {\n            /* 忽略 */\n        }\n        if (!动了) {\n            // ★ 点击 → 开/关窗\n            const 开着 = !!d.getElementById(窗ID);\n            if (开着) {\n                关窗(d);\n                球.classList.remove('on');\n            }\n            else {\n                const p = 夹取({ x: parseFloat(球.style.left) || p0.x, y: parseFloat(球.style.top) || p0.y }, d);\n                开窗(d, p);\n                球.classList.add('on');\n            }\n            return;\n        }\n        // ★ 拖完 → 吸附到最近的一边\n        const ww = d.defaultView?.innerWidth ?? 1200;\n        const wh = d.defaultView?.innerHeight ?? 800;\n        let x = parseFloat(球.style.left) || 0;\n        let y = parseFloat(球.style.top) || 0;\n        const 左 = x + 26 < ww / 2;\n        x = 左 ? 8 : ww - 60;\n        y = Math.max(8, Math.min(wh - 60, y));\n        球.style.transition = 'left .16s ease, top .16s ease';\n        球.style.left = `${x}px`;\n        球.style.top = `${y}px`;\n        (d.defaultView ?? window).setTimeout?.(() => {\n            球.style.transition = '';\n        }, 200);\n        存位(d, { x, y });\n    };\n    球.addEventListener('pointerup', 松);\n    球.addEventListener('pointercancel', 松);\n    // ★ 窗口 resize → 重新夹取\n    const onResize = () => {\n        const p = 夹取({ x: parseFloat(球.style.left) || 0, y: parseFloat(球.style.top) || 0 }, d);\n        球.style.left = `${p.x}px`;\n        球.style.top = `${p.y}px`;\n        存位(d, p);\n    };\n    d.defaultView?.addEventListener('resize', onResize);\n    return () => {\n        (d.defaultView ?? window).clearInterval?.(定时);\n        d.defaultView?.removeEventListener('resize', onResize);\n        d.getElementById(窗ID)?.remove();\n        d.getElementById(球ID)?.remove();\n        d.querySelectorAll(`.${层ID}`).forEach((e) => e.remove());\n    };\n}\n// ══════════════════════════════════════════\n// 生命周期\n// ══════════════════════════════════════════\nlet 销毁;\n$(() => {\n    errorCatched(() => {\n        const 试 = (n = 0) => {\n            const d = 宿主文档();\n            if (d.body) {\n                销毁 = 建球();\n                // ★ 补每楼面板（延迟一点，等正则先渲染）\n                setTimeout(() => 补楼层面板(), 800);\n                setTimeout(() => 补楼层面板(), 2500);\n                console.info('[神奇手机] 悬浮球已挂载');\n            }\n            else if (n < 40) {\n                setTimeout(() => 试(n + 1), 250);\n            }\n        };\n        试();\n    })();\n});\n// ★ 新楼层渲染后补面板\ntry {\n    eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, () => setTimeout(() => 补楼层面板(), 400));\n    eventOn(tavern_events.MESSAGE_UPDATED, () => setTimeout(() => 补楼层面板(), 400));\n}\ncatch {\n    /* 事件不可用就靠上面那两次定时 */\n}\n$(window).on('pagehide', () => {\n    try {\n        销毁?.();\n    }\n    catch {\n        /* 忽略 */\n    }\n});\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///./src/神奇手机/神奇手机/脚本/悬浮球/index.ts\n\n}");
